<div class="page-title clearfix"><h1>Cuenta: <?php echo esc($account->name); ?></h1><a class="btn btn-default pull-right" href="<?php echo get_uri('financial_accounts'); ?>">Volver</a></div><div class="card card-body mb15"><div class="row text-center"><div class="col-md-3"><b>Saldo inicial</b><br><?php echo to_currency($balance['opening_balance']); ?></div><div class="col-md-3"><b>Entradas</b><br><?php echo to_currency($balance['in']); ?></div><div class="col-md-3"><b>Salidas</b><br><?php echo to_currency($balance['out']); ?></div><div class="col-md-3"><b>Saldo actual</b><br><strong><?php echo to_currency($balance['current']); ?></strong></div></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Dirección</th><th>Importe</th><th>Concepto</th><th>Referencia</th><th>Clase</th><th>Saldo</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?php echo esc($m->movement_date); ?></td><td><?php echo strtoupper(esc($m->direction)); ?></td><td><?php echo to_currency($m->amount); ?></td><td><?php echo esc($m->description); ?></td><td><?php echo esc($m->reference_type.' #'.$m->reference_id); ?></td><td><?php echo $m->movement_role==='reversal'?'Reversa de #'.(int)$m->reversal_of_movement_id:'Original'; ?></td><td><?php echo to_currency($m->running_balance); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
